  // C-001 is gold tier, gets 5% discount on each line
  // DES-HOUR: 10 * 8500 = 85000, discount: 4250
  // DEV-HOUR: 8 * 9500 = 76000, discount: 3800
  // ICON-SET: 3 * 980 = 2940, discount: 147
  // Subtotal: 163940, Total discount: 8197, Total: 155743
  assert.equal(totals.subtotal, 163940);
  assert.equal(totals.discount, 8197);
  assert.equal(totals.total, 155743);
